pub(crate) fn unicode_string_property_members(property: &str) -> Option<UnicodeStringProperty> {
    match property {
        "Emoji_Keycap_Sequence" => Some(UnicodeStringProperty {
            ranges: EMOJI__KEYCAP__SEQUENCE_RANGES,
            strings: EMOJI__KEYCAP__SEQUENCE_STRINGS,
        }),
        "Basic_Emoji" => Some(UnicodeStringProperty {
            ranges: BASIC__EMOJI_RANGES,
            strings: BASIC__EMOJI_STRINGS,
        }),
        "RGI_Emoji_Modifier_Sequence" => Some(UnicodeStringProperty {
            ranges: R_G_I__EMOJI__MODIFIER__SEQUENCE_RANGES,
            strings: R_G_I__EMOJI__MODIFIER__SEQUENCE_STRINGS,
        }),
        "RGI_Emoji_Flag_Sequence" => Some(UnicodeStringProperty {
            ranges: R_G_I__EMOJI__FLAG__SEQUENCE_RANGES,
            strings: R_G_I__EMOJI__FLAG__SEQUENCE_STRINGS,
        }),
        "RGI_Emoji_Tag_Sequence" => Some(UnicodeStringProperty {
            ranges: R_G_I__EMOJI__TAG__SEQUENCE_RANGES,
            strings: R_G_I__EMOJI__TAG__SEQUENCE_STRINGS,
        }),
        "RGI_Emoji_ZWJ_Sequence" => Some(UnicodeStringProperty {
            ranges: R_G_I__EMOJI__Z_W_J__SEQUENCE_RANGES,
            strings: R_G_I__EMOJI__Z_W_J__SEQUENCE_STRINGS,
        }),
        "RGI_Emoji" => Some(UnicodeStringProperty {
            ranges: R_G_I__EMOJI_RANGES,
            strings: R_G_I__EMOJI_STRINGS,
        }),
        _ => None,
    }
}
